static lstr L1214 = {0, 738, "// std/internal/entropy. A seed from the operating system's random source.\012#include <time.h>\012\012static int64_t narra_entropy_seed(void) {\012  uint64_t seed = 0;\012#ifdef _WIN32\012  // rand_s needs _CRT_RAND_S before the first stdlib.h, set in runtime.h; it draws from the system's random source and gives 32 bits at a time.\012  unsigned int low = 0, high = 0;\012  if (rand_s(&low) == 0 && rand_s(&high) == 0) seed = ((uint64_t)high << 32) | low;\012#else\012  FILE* source = fopen(\"/dev/urandom\", \"rb\");\012  if (source != NULL) {\012    if (fread(&seed, sizeof seed, 1, source) != 1) seed = 0;\012    fclose(source);\012  }\012#endif\012  if (seed == 0) {\012    seed = (uint64_t)time(NULL) * 6364136223846793005ULL + (uint64_t)(uintptr_t)&seed;\012  }\012  return (int64_t)seed;\012}\012"};
