static lstr L3638 = {0, 4361, "// Map<K, V> with insertion order. emitmaps.nra fills in the @...@ names for\012// each map type a program uses.\012//\012// Entries sit in insertion order in keys, vals, hashes and alive. idx is an\012// open-addressing table of entry numbers plus one (0 is an empty slot), twice\012// as long as the entries. Removing an entry clears alive and leaves its idx\012// slot, so a probe still runs past it. Inserting after a removal appends a new\012// entry, which moves the key to the end. When the entries are full they are\012// compacted, or doubled when more than half are live.\012\012static @M@* @M@_alloc(int64_t cap) {\012  @M@* m = narra_alloc(sizeof(@M@));\012  m->rc = 1; m->len = 0; m->used = 0; m->cap = cap; m->mask = cap * 2 - 1;\012  m->keys = narra_alloc(sizeof(@K@) * (size_t)cap);\012  m->vals = narra_alloc(sizeof(@V@) * (size_t)cap);\012  m->hashes = narra_alloc(sizeof(uint64_t) * (size_t)cap);\012  m->alive = narra_alloc((size_t)cap);\012  m->idx = narra_alloc(sizeof(int64_t) * (size_t)(cap * 2));\012  memset(m->idx, 0, sizeof(int64_t) * (size_t)(cap * 2));\012  return m;\012}\012static @M@* @M@_new(int64_t n) {\012  int64_t cap = 8;\012  while (cap < n) cap *= 2;\012  return @M@_alloc(cap);\012}\012static void @M@_retain(@M@* m) {\012  NARRA_RC_RETAIN(m->rc);\012  NARRA_COPY_SHARED(m);\012}\012static void @M@_release(@M@* m) {\012  NARRA_COPY_DROP(m);\012  if (NARRA_RC_RELEASE(m->rc)) {\012    for (int64_t i = 0; i < m->used; i++) {\012      if (m->alive[i]) { @REL_KEY_I@ @REL_VAL_I@ }\012    }\012    narra_free(m->keys); narra_free(m->vals); narra_free(m->hashes);\012    narra_free(m->alive); narra_free(m->idx);\012    narra_free(m);\012  }\012}\012static uint64_t @M@_hash(@K@ k) {\012  uint64_t h = @HASH@(k) * UINT64_C(0x9E3779B97F4A7C15);\012  return h ^ (h >> 32);\012}\012// Returns the entry number of k, or -1.\012static int64_t @M@_lookup(@M@* m, @K@ k) {\012  uint64_t h = @M@_hash(k);\012  int64_t i = (int64_t)(h & (uint64_t)m->mask);\012  for (;;) {\012    int64_t s = m->idx[i];\012    if (s == 0) return -1;\012    if (m->alive[s - 1] && m->hashes[s - 1] == h && @EQ@(m->keys[s - 1], k)) return s - 1;\012    i = (i + 1) & m->mask;\012  }\012}\012// Returns a map the caller owns alone, copying it when it is shared.\012static @M@* @M@_unique(@M@* m) {\012  if (!NARRA_RC_UNSHARE(m->rc)) return m;\012  NARRA_COPY_WRITE(m, 2);\012  @M@* c = @M@_alloc(m->cap);\012  memcpy(c->keys, m->keys, sizeof(@K@) * (size_t)m->used);\012  memcpy(c->vals, m->vals, sizeof(@V@) * (size_t)m->used);\012  memcpy(c->hashes, m->hashes, sizeof(uint64_t) * (size_t)m->used);\012  memcpy(c->alive, m->alive, (size_t)m->used);\012  memcpy(c->idx, m->idx, sizeof(int64_t) * (size_t)(m->cap * 2));\012  c->len = m->len; c->used = m->used;\012  for (int64_t i = 0; i < c->used; i++) {\012    if (c->alive[i]) { @RET_KEY_C@ @RET_VAL_C@ }\012  }\012  NARRA_COPY_WRITTEN();\012  @M@_release(m);\012  return c;\012}\012// Moves the live entries to the front of arrays of capacity cap.\012static void @M@_rebuild(@M@* m, int64_t cap) {\012  @M@* n = @M@_alloc(cap);\012  int64_t j = 0;\012  for (int64_t i = 0; i < m->used; i++) {\012    if (!m->alive[i]) continue;\012    n->keys[j] = m->keys[i]; n->vals[j] = m->vals[i];\012    n->hashes[j] = m->hashes[i]; n->alive[j] = 1;\012    int64_t s = (int64_t)(n->hashes[j] & (uint64_t)n->mask);\012    while (n->idx[s]) s = (s + 1) & n->mask;\012    n->idx[s] = j + 1;\012    j++;\012  }\012  narra_free(m->keys); narra_free(m->vals); narra_free(m->hashes);\012  narra_free(m->alive); narra_free(m->idx);\012  m->keys = n->keys; m->vals = n->vals; m->hashes = n->hashes;\012  m->alive = n->alive; m->idx = n->idx;\012  m->cap = cap; m->mask = n->mask; m->used = j;\012  narra_free(n);\012}\012// Stores v under k. Takes over k and v.\012static void @M@_set(@M@** p, @K@ k, @V@ v) {\012  @M@* m = *p;\012  int64_t e = @M@_lookup(m, k);\012  if (e >= 0) {\012    m = @M@_unique(m); *p = m;\012    @REL_VAL_E@\012    m->vals[e] = v;\012    @REL_KEY_ARG@\012    return;\012  }\012  m = @M@_unique(m); *p = m;\012  if (m->used == m->cap) @M@_rebuild(m, m->len * 2 > m->cap \077 m->cap * 2 : m->cap);\012  uint64_t h = @M@_hash(k);\012  int64_t i = m->used++;\012  m->keys[i] = k; m->vals[i] = v; m->hashes[i] = h; m->alive[i] = 1;\012  m->len++;\012  int64_t s = (int64_t)(h & (uint64_t)m->mask);\012  while (m->idx[s]) s = (s + 1) & m->mask;\012  m->idx[s] = i + 1;\012}\012// Removes k and reports whether it was there. Borrows k.\012static bool @M@_remove(@M@** p, @K@ k) {\012  int64_t e = @M@_lookup(*p, k);\012  if (e < 0) return false;\012  @M@* m = @M@_unique(*p); *p = m;\012  @REL_KEY_E@\012  @REL_VAL_E@\012  m->alive[e] = 0;\012  m->len--;\012  return true;\012}\012"};
